import json,pathlib
p=pathlib.Path('.book-work/planetaryskyunderstandingthecolorsaboveus-v1-7d866fc6ab2a/translations/ro/full/chunks')
t={
't000053':'''Aspectul cerului este strâns legat de climă și vreme. Umiditatea, temperatura, formațiunile noroase și fenomenele extreme contribuie toate la modelarea tabloului de deasupra noastră. Umiditatea și temperatura sunt factori atmosferici fundamentali, care influențează puternic cerul. Interacțiunea lor afectează nu numai priveliștea, ci și tiparele vremii, formarea norilor și condițiile generale ale atmosferei. Umiditatea ridicată poate crea un cer mai încețoșat, datorită prezenței sporite a vaporilor de apă. Umezeala împrăștie lumina în mai multe feluri, producând adesea un aspect alb-lăptos sau cenușiu. Când umiditatea este mare, vaporii se condensează în picături mici, care împrăștie lumina solară mai difuz decât aerul uscat. Prin urmare, obiectele îndepărtate pot părea neclare sau ascunse, iar vizibilitatea scade.''',
't000054':'''Fenomenul se observă mai ales în regiunile de coastă și în perioadele ploioase, când umiditatea și norii pot crea un cer acoperit, lipsit de culorile vii ale vremii senine. Totuși, umiditatea ridicată poate favoriza norii și poate intensifica apusurile. Când aerul este saturat de umezeală, norii pot lua forme și straturi complicate, dând adâncime și textură cerului. Picăturile suspendate refractă și împrăștie lumina, creând o paletă bogată la răsărit și apus. Pot apărea spectacole de portocaliu, roz și violet, adesea mai pronunțate în condiții umede. Culorile devin deosebit de vizibile când Soarele se află jos, iar lumina lui străbate un strat mai gros de atmosferă, întâlnind mai multă umezeală și mai multe particule.''',
't000055':'''Temperatura are și ea un rol decisiv în aspectul cerului. Aerul rece conține de obicei mai puțină umezeală decât cel cald, favorizând ceruri mai limpezi și de un albastru mai adânc. De aceea, zilele de iarnă din climatele uscate pot avea un cer deosebit de albastru. Cantitatea redusă de apă în aer micșorează anumite forme de împrăștiere și lasă o culoare mai vie. Aerul cald poate reține mai multă umezeală, aducând pâclă și un cer mai tern. Când temperatura crește, aerul devine mai ascendent, iar stabilitatea atmosferei scade adesea. Turbulența rezultată poate modifica împrăștierea luminii și culoarea generală a cerului. Inversiunile termice sunt un alt mod important în care temperatura influențează priveliștea: un strat de aer cald prinde aerul rece aproape de sol și împiedică dispersarea poluanților.''',
't000056':'''În această situație, concentrațiile de particule și gaze pot crește în atmosfera joasă, schimbând vizibil culoarea și limpezimea cerului. În timpul inversiunilor, cerul poate părea mai șters, iar poluanții acumulați reduc mult vizibilitatea. Fenomenul este des întâlnit în orașe, unde activitățile umane contribuie la poluare și la păstrarea pâclei. Relația dintre umiditate și temperatură este complexă și dinamică, influențând atât culoarea cerului, cât și formarea și comportamentul norilor. De pildă, aerul cald și umed se răcește și condensează atunci când urcă, formând nori.''',
't000057':'''Grosimea, înălțimea și tipul norilor influențează direct aspectul cerului. Norii cumulus pot crea un cer presărat cu spații albastre strălucitoare, în timp ce stratus poate produce o întindere cenușie uniformă. Umiditatea și temperatura sunt, așadar, factori esențiali. Umiditatea ridicată poate aduce pâclă și culori mai intense la răsărit și apus, iar temperatura schimbă cantitatea de umezeală și stabilitatea aerului, influențând culoarea și limpezimea. Înțelegerea acestei relații ne ajută să apreciem frumusețea atmosferei și caracterul dinamic al vremii și climei. Variațiile cerului ne amintesc de interacțiunile complexe care ne modelează continuu mediul. Norii sunt poate elementul cel mai vizibil și mai schimbător al acestui tablou.''',
't000058':'''Diferitele tipuri de nori pot schimba radical culoarea, textura și atmosfera cerului. Norii cumulus, albi și pufoși, asociați adesea vremii bune, creează clasicul cer „parțial noros”. Ei se formează prin curenți de convecție și pot fi mici și răzleți sau mari și impunători.''',
't000059':'''Norii stratus se formează, în schimb, în straturi orizontale și pot acoperi întregul cer cu un gri uniform. Ei apar adesea în condiții atmosferice stabile și pot persista mult timp, modificând priveliștea zile întregi. Sus, norii cirrus trasează forme subțiri și delicate. Sunt alcătuiți din cristale de gheață și pot anunța schimbarea vremii. Împrăștiind și refractând lumina Soarelui la altitudine, ei pot contribui la apusuri spectaculoase. Printre cele mai dramatice formațiuni sunt norii cumulonimbus, înalți și denși, asociați furtunilor. Ei pot întuneca puternic cerul, creând contraste izbitoare între lumină și umbră. Întunericul apare deoarece grosimea și întinderea lor verticală blochează multă lumină solară.''',
't000060':'''Norii schimbă culoarea cerului nu doar prin prezență, ci și prin felul în care interacționează cu lumina. Ei reflectă și împrăștie razele în moduri complexe, creând numeroase efecte vizuale. La răsărit și apus, norii pot deveni o pânză pictată în roșu, portocaliu și violet, reflectând și refractând lumina Soarelui. Vremea extremă poate produce unele dintre cele mai neobișnuite și mai impresionante ceruri. Furtunile pot crea uneori un cer verde, fenomen încă neînțeles pe deplin, posibil legat de împrăștierea luminii prin picături de apă și gheață. Furtunile severe pot aduce și nori mammatus, cu aspect de pungi, care semnalează adesea o atmosferă turbulentă. Furtunile de praf pot colora cerul în portocaliu sau maro, deoarece particulele împrăștie lumina în mod neobișnuit.''',
't000061':'''În cazuri grave, furtunile de praf pot opri suficientă lumină încât ziua să capete un întuneric straniu, schimbând radical priveliștea. Erupțiile vulcanice influențează puternic cerul, uneori la scară globală. Cenușa și gazele eliberate de erupții mari pot produce apusuri roșii intense în întreaga lume, fenomen consemnat de-a lungul istoriei. Ele pot și să slăbească lumina solară în ansamblu, lăsând un cer cenușiu care persistă luni sau chiar ani după evenimente foarte mari.''',
't000062':'''Uraganele și ciclonii produc aspecte aparte ale cerului. În ochiul furtunii poate fi senin și liniște, înconjurate de nori foarte înalți, ceea ce dă o înșelătoare impresie de pace în mijlocul haosului. Furtuna care se apropie poate întuneca cerul și îi poate da o tentă verde sau galbenă, asociată de mult timp cu vremea severă. În regiunile polare, condițiile atmosferice speciale creează spectacole impresionante. Norii stratosferici polari pot produce irizații în culori pastelate. Aurora boreală, luminile nordului, colorează noaptea în nuanțe vii, când vântul solar interacționează cu câmpul magnetic al Pământului. Înțelegerea acestor efecte meteorologice asupra cerului nu are doar valoare estetică, ci și aplicații practice.''',
't000063':'''Multe fenomene meteorologice pot fi anticipate ori recunoscute observând schimbările cerului, ceea ce face cunoașterea utilă meteorologilor și celor pasionați de natură. Cerurile neobișnuite sunt adesea legate de evenimente atmosferice importante și pot oferi indicii cercetătorilor care studiază schimbările de durată ale atmosferei. În fața unei variabilități climatice tot mai mari, capacitatea de a citi aceste semne devine importantă atât pentru știință, cât și pentru conștientizarea publică. Aspectul cerului rezultă din interacțiunea complexă dintre umezeală, temperatură, nori și fenomene meteorologice. Înțelegându-le, apreciem mai mult frumusețea de deasupra noastră și aflăm lucruri valoroase despre funcționarea și transformările atmosferei.'''
}
seen=set()
for n in (9,10):
 f=p/f'{n:04}.json';d=json.loads(f.read_text())
 for x in d['segments']:
  assert not x['translation'] and x['id'] in t;x['translation']=t[x['id']];seen.add(x['id'])
 f.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
assert seen==set(t)
print('Translated',len(seen))
